// app/dashboard/page.tsx (Server Component by default)
import { Chart } from './Chart';
import { RefreshButton } from './RefreshButton';
import { db } from '@/lib/db';

export default async function Page() {
  const metrics = await db.metrics.findMany();

  return (
    <main>
      <h1>Dashboard</h1>
      <Chart data={metrics} />
      <RefreshButton onRefresh={() => db.metrics.findMany()} />
    </main>
  );
}

// app/dashboard/Chart.tsx
import { useState } from 'react';
import type { Metric } from '@/lib/report';

export function Chart({ data }: { data: Metric[] }) {
  const [zoom, setZoom] = useState(1);
  const peak = Math.max(...data.map((m) => m.value));
  return <canvas data-zoom={zoom} data-peak={peak} onClick={() => setZoom((z) => z + 0.1)} />;
}

// app/dashboard/RefreshButton.tsx
'use client';

export function RefreshButton({ onRefresh }: { onRefresh: () => void }) {
  return <button onClick={() => onRefresh()}>Refresh</button>;
}

scenarios.modelAnswer:
Both errors are the same mistake seen from two sides: a client capability and a non-serializable value are used across the RSC boundary. The directive is not a rendering switch — it is the edge of the server module graph.

**Predict before running**

1. `Chart` calls `useState` and has no directive, so it compiles as a Server Component. State is a client capability, so the server render throws `useState only works in Client Components`.
2. `onRefresh={() => db.metrics.findMany()}` is a closure created in a Server Component and passed into a Client Component. Props crossing into `'use client'` must be serializable, and a bare function is not, hence `Functions cannot be passed directly to Client Components`. It is a design error too, not only a type error: the handler would run a database query from a browser-reachable path.

**Fix 1 — the directive belongs to the leaf.** `'use client'` at the top of `Chart.tsx` turns that file into an entry point of the client module graph: the file and its imports (the chart library, any helper it pulls in) join the client bundle, which is the whole cost model, and the directive never propagates upward (https://nextjs.org/docs/app/api-reference/directives/use-client). The usual repair — `'use client'` on `page.tsx` — clears both errors and pays for them: the page and its import graph become client code and `db` lands on the browser side of the boundary, where it cannot run, so the query has to move to an API route and the dashboard loses its server-rendered content.

**Fix 2 — remove the function prop instead of threading it.** A refresh is a client concern: the button owns it with `router.refresh()`, which makes a new request to the server, re-fetches data requests and re-renders the Server Components, merging the new RSC payload without discarding client state or scroll position (https://nextjs.org/docs/app/api-reference/functions/use-router). If the server must own the work, the supported crossing is a Server Function marked `'use server'`, imported by the client module — but returning rows does not update already-rendered server output; the route still has to re-render.

**Fix 3 — the payload is the remaining cost.** Props of a Client Component are serialized into the RSC payload sent to the browser, so handing every `Metric` row to a chart that only needs the peak ships rows nobody renders. Aggregate on the server and pass a number.

**Refresh is not invalidation.** `router.refresh()` clears the client cache for the route but does not invalidate the server-side cache, so a cached read can come back unchanged; if the metrics read is cached under Cache Components, pair the refresh with the invalidation call of that model (`updateTag` for read-your-own-writes, `revalidateTag` when stale-while-revalidate is acceptable). Note also that with `cacheComponents` enabled an uncached read such as `db.metrics.findMany()` must sit inside `use cache` or behind a `<Suspense>` boundary, or the route is flagged as blocking the prerender — which is the shape the fixed tree uses anyway.

```tsx
// app/dashboard/page.tsx — stays a Server Component
import { Suspense } from 'react';
import { Chart } from './Chart';
import { RefreshButton } from './RefreshButton';
import { db } from '@/lib/db';

export default function Page() {
  return (
    <main>
      <h1>Dashboard</h1>
      <Suspense fallback={<p>Loading metrics…</p>}>
        <MetricsPanel />
      </Suspense>
      <RefreshButton />
    </main>
  );
}

async function MetricsPanel() {
  const metrics = await db.metrics.findMany();
  const peak = Math.max(...metrics.map((m) => m.value));
  return <Chart peak={peak} />;
}

// app/dashboard/Chart.tsx
'use client';

import { useState } from 'react';

export function Chart({ peak }: { peak: number }) {
  const [zoom, setZoom] = useState(1);
  return <canvas data-zoom={zoom} data-peak={peak} onClick={() => setZoom((z) => z + 0.1)} />;
}

// app/dashboard/RefreshButton.tsx
'use client';

import { useRouter } from 'next/navigation';
import { useTransition } from 'react';

export function RefreshButton() {
  const router = useRouter();
  const [pending, startTransition] = useTransition();

  return (
    <button disabled={pending} onClick={() => startTransition(() => router.refresh())}>
      {pending ? 'Refreshing…' : 'Refresh'}
    </button>
  );
}
```

What stays true in the fixed tree: `page.tsx` and `MetricsPanel` are Server Components, `Chart` is still rendered to HTML on the server and hydrated, the only JavaScript shipped is the two leaves, and Refresh re-renders the server output instead of calling the database from the browser. Sources: https://nextjs.org/docs/app/api-reference/directives/use-client, https://nextjs.org/docs/app/getting-started/server-and-client-components, https://nextjs.org/docs/app/api-reference/functions/use-router, https://nextjs.org/docs/app/getting-started/caching.

