// app/projects/actions.ts
'use server';

import { db } from '@/lib/db';

export async function renameProject(formData: FormData) {
  const userId = String(formData.get('userId'));
  const projectId = String(formData.get('projectId'));
  const name = String(formData.get('name'));

  const project = await db.project.update({
    where: { id: projectId },
    data: { name, updatedBy: userId },
  });

  return project;
}

// app/projects/rename-form.tsx
'use client';

import { renameProject } from './actions';

export function RenameForm({ projectId, userId }: { projectId: string; userId: string }) {
  return (
    <form action={renameProject}>
      <input type="hidden" name="projectId" value={projectId} />
      <input type="hidden" name="userId" value={userId} />
      <input name="name" />
      <button type="submit">Rename</button>
    </form>
  );
}

scenarios.modelAnswer:
The directive does not make this function private; it makes it reachable. `'use server'` turns `renameProject` into a request endpoint that any caller can invoke with an arbitrary body, so everything inside has to be written for an untrusted caller (https://nextjs.org/docs/app/api-reference/directives/use-server).

**Defects, in severity order**

1. **Identity is taken from the form.** `userId` is a hidden input, so the caller chooses who they are. Derive the user from the server-side session instead (`cookies()` plus session verification) and never accept an identity from the payload. A hidden field is presentation, not authorization.
2. **No authorization against the resource.** The function updates whatever `projectId` arrives. Even with a real session, anyone can rename another tenant's project by changing the id — a textbook IDOR. The check belongs next to the data: load and update the project scoped to the session user (`renameProjectForUser(userId, projectId, name)`), and return a small not-found/forbidden result when ownership does not match.
3. **No validation.** `String(formData.get('name'))` accepts an empty string, whitespace, or an unbounded payload. Validate and normalize (trim, length, allowed characters) before the write and fail with a typed error the form can render.
4. **The raw row is returned.** Server Function return values are serialized to the client, so the whole record — owner id, internal notes, every selected column — ships to the browser. Return `{ ok: true }` or the minimum fields the UI needs.
5. **Nothing is revalidated.** After the write, cached reads still show the old name. Revalidate the affected path or tag inside the function, using the API of the caching model the app runs (see the caching question).

**Fixed version**

```ts
// app/projects/actions.ts
'use server';

import { revalidateTag } from 'next/cache';
import { requireUser } from '@/lib/dal/session';
import { renameProjectForUser } from '@/lib/dal/projects';

export async function renameProject(formData: FormData) {
  const projectId = String(formData.get('projectId') ?? '');
  const name = String(formData.get('name') ?? '').trim();
  if (!projectId || name.length === 0 || name.length > 80) {
    return { ok: false as const, error: 'invalid-input' };
  }

  const user = await requireUser(); // session-derived identity
  const updated = await renameProjectForUser(user.id, projectId, name);
  if (!updated) return { ok: false as const, error: 'not-found' };

  revalidateTag('projects');
  return { ok: true as const };
}
```

**What to say out loud:** the mutation lives behind a Data Access Layer function whose first argument is the session identity, and the directive is read as "this is a public boundary" — the same checklist you would apply to a Route Handler. Also note that `proxy` does not transform `'use server'`: an auth redirect there is an optimistic pre-check, not a guard around this function.

